#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct { float x, y, z; } Vec3;
typedef struct { Vec3 origin, direction; } Ray;
typedef struct { float t; Vec3 point, normal; int hit; } Hit;

static Vec3 vc(float x, float y, float z) { Vec3 v = {x, y, z}; return v; }
static Vec3 vadd(Vec3 a, Vec3 b) { return vc(a.x + b.x, a.y + b.y, a.z + b.z); }
static Vec3 vsub(Vec3 a, Vec3 b) { return vc(a.x - b.x, a.y - b.y, a.z - b.z); }
static Vec3 vmul(Vec3 a, float s) { return vc(a.x * s, a.y * s, a.z * s); }
static float vdot(Vec3 a, Vec3 b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
static Vec3 vnorm(Vec3 v) {
    float l = sqrtf(v.x * v.x + v.y * v.y + v.z * v.z);
    return vc(v.x / l, v.y / l, v.z / l);
}
static Ray ray_create(Vec3 o, Vec3 d) {
    Ray r; r.origin = o; r.direction = vnorm(d); return r;
}
static Vec3 ray_at(Ray r, float t) { return vadd(r.origin, vmul(r.direction, t)); }

static Hit sphere_intersect(Ray ray, Vec3 center, float radius) {
    Hit h; Vec3 oc = vsub(ray.origin, center);
    float a = vdot(ray.direction, ray.direction);
    float b = 2.0f * vdot(oc, ray.direction);
    float c = vdot(oc, oc) - radius * radius;
    float disc = b * b - 4.0f * a * c;
    h.hit = 0; h.t = 0; h.point = vc(0, 0, 0); h.normal = vc(0, 0, 0);
    if (disc < 0.0f) return h;
    float sq = (float)sqrt(disc);
    float t = (float)((-b - sq) / (2.0f * a));
    if (t < 0.001f) {
        t = (float)((-b + sq) / (2.0f * a));
        if (t < 0.001f) return h;
    }
    h.hit = 1; h.t = t;
    h.point = ray_at(ray, t);
    h.normal = vnorm(vsub(h.point, center));
    return h;
}

static Hit plane_intersect(Ray ray, Vec3 normal, float d) {
    Hit h;
    float denom = vdot(ray.direction, normal);
    h.hit = 0; h.t = 0; h.point = vc(0, 0, 0); h.normal = vc(0, 0, 0);
    if (fabsf(denom) < 0.0001f) return h;
    float t = (d - vdot(ray.origin, normal)) / denom;
    if (t < 0.001f) return h;
    h.hit = 1; h.t = t; h.point = ray_at(ray, t); h.normal = normal;
    return h;
}

static Vec3 sky_color(Vec3 dir) {
    float t = 0.5f * (dir.y + 1.0f);
    return vc(1.0f - 0.5f * t, 1.0f - 0.7f * t, 1.0f - t);
}

static const Vec3 sphere_center = {0.0f, -0.5f, -5.0f};
static const float sphere_radius = 1.0f;
static const Vec3 light_dir = {0.57735026f, 0.57735026f, -0.57735026f};

static Vec3 trace(Ray ray) {
    Hit hs = sphere_intersect(ray, sphere_center, sphere_radius);
    Hit hp = plane_intersect(ray, vc(0, 1, 0), -1.5f);
    Hit h;
    int is_sphere;
    if (hs.hit && (!hp.hit || hs.t < hp.t)) { h = hs; is_sphere = 1; }
    else if (hp.hit) { h = hp; is_sphere = 0; }
    else return sky_color(ray.direction);
    Ray sr = ray_create(vadd(h.point, vmul(h.normal, 0.001f)), light_dir);
    Hit sh = sphere_intersect(sr, sphere_center, sphere_radius);
    float intensity;
    if (sh.hit) intensity = 0.2f;
    else {
        float diff = fmax(vdot(h.normal, light_dir), 0.0f);
        intensity = 0.2f + 0.8f * diff;
    }
    if (is_sphere) return vmul(vc(1.0f, 0.2f, 0.2f), intensity);
    float c = ((int)(floorf(h.point.x) + floorf(h.point.z)) & 1) ? 0.4f : 0.9f;
    return vc(c * intensity, c * intensity, c * intensity);
}

int main(void) {
    int W = 800, H = 600;
    Vec3 **img = malloc(H * sizeof(Vec3 *));
    for (int y = 0; y < H; y++) img[y] = malloc(W * sizeof(Vec3));
    fprintf(stderr, "Creating high-resolution image: %dx%d\n", W, H);
    fputs("This will be downsampled with ffmpeg after rendering\n", stderr);
    fputs("Rendering high-resolution image...\n", stderr);
    for (int y = 0; y < H; y++) {
        fprintf(stderr, "\rProgress: %.1f%%", 100.0f * (float)y / (float)H);
        for (int x = 0; x < W; x++) {
            Vec3 d = vc(((float)x / (float)(W - 1)) * 2.6666667f - 1.3333334f,
                        2.0f * (1.0f - (float)y / (float)(H - 1)) - 1.0f,
                        -1.0f);
            img[y][x] = trace(ray_create(vc(0, 0, 0), d));
        }
    }
    fputs("\nRendering complete\n", stderr);
    FILE *f = fopen("image.ppm", "w");
    if (!f) { fprintf(stderr, "Error: Could not open file %s for writing\n", "image.ppm"); return 1; }
    fprintf(f, "P3\n%d %d\n255\n", W, H);
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            Vec3 c = img[y][x];
            float r = fmin(fmax(c.x, 0.0), 1.0);
            float g = fmin(fmax(c.y, 0.0), 1.0);
            float b = fmin(fmax(c.z, 0.0), 1.0);
            fprintf(f, "%d %d %d\n", (int)(r * 255.99f), (int)(g * 255.99f), (int)(b * 255.99f));
        }
    }
    fclose(f);
    fprintf(stderr, "Wrote image to %s\n", "image.ppm");
    fputs("Done.\n", stderr);
    for (int y = 0; y < H; y++) free(img[y]);
    free(img);
    return 0;
